//! The mobile app's native project inputs, as a Tauri plugin (design D.4, generator model G-a): `gen/android` is
//! regenerated by the Tauri CLI, never edited by hand, so what the Android app needs beyond the template lives in the
//! Android library under `android/`, whose manifest and resources Gradle merges into the app's.
use tauri::{plugin::TauriPlugin, Runtime};

pub fn init<R: Runtime>() -> TauriPlugin<R> {
    tauri::plugin::Builder::new("mobile").build()
}
